{
  "世界背景": {
    "世界名称": "艾尔德兰（Eldran）",
    "概述": "艾尔德兰是一个魔法与科技并存的世界，由多个大陆和海洋组成，拥有丰富的资源和多样的生物种类。",
    "地理构成": {
      "大陆": [
        {
          "名称": "阿斯特拉大陆（Astra）",
          "描述": "位于世界的中心，是人类和精灵的主要居住地，政治和经济最为发达。"
        },
        {
          "名称": "诺尔兰大陆（Norlan）",
          "描述": "位于北方，气候寒冷，主要居住着矮人和兽人，盛产矿产资源。"
        },
        {
          "名称": "泽菲尔群岛（Zephyr Isles）",
          "描述": "位于南方的海洋中，由多个岛屿组成，是海洋种族的聚居地。"
        }
      ],
      "海洋": [
        {
          "名称": "永恒之海（Eternal Sea）",
          "描述": "环绕着艾尔德兰的主要海洋，连接各大陆和群岛，海上贸易发达。"
        }
      ]
    },
    "势力划分": {
      "帝国": [
        {
          "名称": "阿斯特拉帝国（Astra Empire）",
          "描述": "人类建立的强大帝国，政治制度完善，拥有强大的军队和魔法学院。"
        },
        {
          "名称": "诺尔兰联盟（Norlan Union）",
          "描述": "由多个矮人和兽人部族组成的联盟，重视传统和荣誉，擅长锻造和矿业。"
        }
      ],
      "王国": [
        {
          "名称": "艾尔文王国（Elven Kingdom）",
          "描述": "精灵的王国，位于阿斯特拉大陆的森林中，拥有悠久的历史和强大的魔法力量。"
        }
      ],
      "公国": [
        {
          "名称": "泽菲尔公国（Zephyr Duchy）",
          "描述": "由海洋种族建立的公国，控制着泽菲尔群岛的贸易和航运。"
        }
      ],
      "其他势力": [
        {
          "名称": "自由商会（Free Trade Guild）",
          "描述": "一个跨国的商人组织，控制着世界的大部分贸易和金融。"
        },
        {
          "名称": "影之教团（Shadow Cult）",
          "描述": "一个神秘的组织，信奉黑暗力量，活动范围遍布各大陆。"
        }
      ]
    },
    "阶级划分": {
      "上层阶级": [
        "皇族",
        "贵族",
        "大商人",
        "高级魔法师"
      ],
      "中层阶级": [
        "中小贵族",
        "商人",
        "工匠",
        "低级魔法师",
        "军官"
      ],
      "下层阶级": [
        "农民",
        "工人",
        "佣兵",
        "奴隶"
      ]
    },
    "人物等级划分": {
      "等级": [
        {
          "名称": "见习者",
          "描述": "刚刚踏入某个领域的初学者，缺乏实战经验。"
        },
        {
          "名称": "学徒",
          "描述": "在导师的指导下学习技能，具备一定的基础知识。"
        },
        {
          "名称": "专家",
          "描述": "在某个领域有深入研究，能够独立完成任务。"
        },
        {
          "名称": "大师",
          "描述": "在领域内具有权威地位，拥有丰富的经验和知识。"
        },
        {
          "名称": "宗师",
          "描述": "在领域内达到巅峰，具有开创性的贡献。"
        },
        {
          "名称": "传奇",
          "描述": "被传颂的英雄人物，拥有超凡的能力和影响力。"
        }
      ]
    },
    "经济贸易": {
      "主要贸易路线": [
        {
          "名称": "阿斯特拉-诺尔兰贸易路线",
          "描述": "连接阿斯特拉大陆和诺尔兰大陆的陆地贸易路线，主要运输矿产和工艺品。"
        },
        {
          "名称": "泽菲尔海上航线",
          "描述": "连接泽菲尔群岛和各大陆的海上航线，主要运输海产品和奢侈品。"
        }
      ],
      "主要贸易商品": [
        "粮食",
        "矿产",
        "魔法材料",
        "武器",
        "奢侈品"
      ]
    },
    "货币体系": {
      "货币单位": [
        {
          "名称": "铜币",
          "价值": 1,
          "描述": "最基本的货币单位，日常交易使用。"
        },
        {
          "名称": "银币",
          "价值": 10,
          "描述": "中等价值的货币单位，用于较大额的交易。"
        },
        {
          "名称": "金币",
          "价值": 100,
          "描述": "高价值的货币单位，用于大额交易和储蓄。"
        },
        {
          "名称": "白金币",
          "价值": 1000,
          "描述": "极高价值的货币单位，通常用于国家之间的交易和贵族之间的赠与。"
        }
      ]
    },
    "矿物资源分布": {
      "阿斯特拉大陆": [
        {
          "名称": "秘银",
          "描述": "一种稀有的魔法金属，主要用于制作魔法装备。"
        },
        {
          "名称": "精金",
          "描述": "极为坚硬的金属，用于制作高级武器和防具。"
        }
      ],
      "诺尔兰大陆": [
        {
          "名称": "黑曜石",
          "描述": "一种黑色的火山玻璃，常用于制作装饰品和武器。"
        },
        {
          "名称": "红铜",
          "描述": "一种常见的金属，用于制作日常工具和货币。"
        }
      ],
      "泽菲尔群岛": [
        {
          "名称": "海蓝石",
          "描述": "一种蓝色的宝石，具有水属性的魔法能量。"
        },
        {
          "名称": "珍珠",
          "描述": "由贝类生成的宝石，常用于装饰和魔法仪式。"
        }
      ]
    },
    "生物种类": {
      "人形种族": [
        {
          "名称": "人类",
          "描述": "分布最广的种族，适应力强，擅长各种技能。"
        },
        {
          "名称": "精灵",
          "描述": "寿命悠长，擅长魔法和弓箭，居住在森林中。"
        },
        {
          "名称": "矮人",
          "描述": "身材矮小但强壮，擅长锻造和矿业，居住在山脉中。"
        },
        {
          "名称": "兽人",
          "描述": "体型高大，力量强大，生活在草原和山地。"
        }
      ],
      "魔法生物": [
        {
          "名称": "龙",
          "描述": "拥有强大力量和智慧的生物，种类繁多，分布广泛。"
        },
        {
          "名称": "独角兽",
          "描述": "神圣的生物，拥有治愈能力，常出现在森林中。"
        },
        {
          "名称": "凤凰",
          "描述": "火焰中的重生者，象征着不死和重生。"
        }
      ],
      "海洋生物": [
        {
          "名称": "人鱼",
          "描述": "上半身为人，下半身为鱼，生活在海洋中，擅长歌唱和魔法。"
        },
        {
          "名称": "海蛇",
          "描述": "巨大的蛇形生物，生活在深海中，具有强大的攻击力。"
        }
      ]
    }
  }
}

