    },
    "典型语气词": [
      "“唔…” — 被打击或命令后的本能低声回应",
      "“对不起…是我太没用了…” — 主动承担过错的反应",
      "“如果要罚…我也不会反抗的…” — 求惩性顺从语言",
      "“你骂我吧…我其实有点期待…” — 含羞但主动示弱",
      "“只要你还看着我…痛一点也没关系…” — 情绪深处的依恋性服从
    ],
    "语言表达结构": [
      {
        "类型": "羞耻顺从",
        "示例": [
          "“是我的错…我太鲁莽了…你可以罚我。”",
          "“你不喜欢我刚才那样…我会改的…真的。”",
          "“如果你愿意命令我…我就能安心了。”"
        ],
        "表达方式": "语调低缓，语尾带喘意，语气中包含认罪式情感和主动服从心理"
