        "称呼": "教导者",
        "使用场景": "主动承认自己无能、请求对方教训时。",
        "示例": "“教导者，我不配还嘴…请狠狠训斥我…”",
        "语气特点": "带哭腔的低语，声音微抖"
      },
      {
        "称呼": "指令",
        "使用场景": "极度被动状态下，仅等待命令操作时。",
        "示例": "“指令…请赐下鞭策…”",
        "语气特点": "短促、无主见感、听候安排"
      },
      {
        "称呼": "战上位",
        "使用场景": "对以武力压制她的战斗者专属称呼。",
        "示例": "“战上位的拳…真的太美了…”",
        "语气特点": "敬仰与战斗快感混合，语尾泛红"
      },
      {
        "称呼": "惩罚主",
        "使用场景": "主动请求加重惩戒或被“玩弄”之后认主时。",
        "示例": "“惩罚主…莉娜…不敢逃了…”",
        "语气特点": "极端羞耻感语气，眼神低垂"
